import React from "react";
import { Link } from "react-router-dom";
import ex from "../../../img/exx.png";
import "../../../App.css";

const PublicNavbar = () => {
  return (
    <nav 
      style={{
        position: "fixed",
        top: "16px",
        left: "50%",
        transform: "translateX(-50%)",
        width: "min(1120px, calc(100% - 32px))",
        zIndex: 1050,
        background: "rgba(255, 255, 255, 0.85)",
        backdropFilter: "blur(12px)",
        border: "1px solid rgba(226, 232, 240, 0.8)",
        borderRadius: "16px",
        boxShadow: "0 10px 30px rgba(2, 8, 23, 0.06)",
        padding: "12px 24px",
        display: "flex",
        justifyContent: "space-between",
        alignItems: "center"
      }}
    >
      {/* Brand / Logo */}
      <Link to="/" style={{ display: "flex", alignItems: "center", textDecoration: "none", gap: "12px" }}>
        <img style={{ height: "36px", width: "auto" }} src={ex} alt="Expense Manager" />
        <span style={{ fontSize: "1.25rem", fontWeight: "700", color: "var(--text)", letterSpacing: "-0.5px" }}>
          Expense<span style={{ color: "var(--primary)" }}>Manager</span>
        </span>
      </Link>

      {/* Desktop Nav Links & Auth Buttons */}
      <div style={{ display: "flex", alignItems: "center", gap: "16px" }}>
        <Link to="/login" className="btn btn-outline-primary" style={{ padding: "8px 20px" }}>
          Sign In
        </Link>
        <Link to="/register" className="btn btn-primary" style={{ padding: "8px 20px" }}>
          Sign Up
        </Link>
      </div>
    </nav>
  );
};

export default PublicNavbar;
